  "underwater-huggs": {"prompt":"Editorial fashion photo, the PERSON FROM THE REFERENCE IMAGE, eyes closed, serene expression, cheek resting on folded hands as if sleeping. White dress with puff sleeves, lace collar and ruffles. Floating underwater hugging a large inflatable shark. Whimsical fairytale glittering flowers are suspended on thin strings above her. Deep dark-blue water, rising bubbles, soft surface shimmer. Realistic skin texture with visible pores. Dreamy, weightless mood. Medium format, Portra film tonality, light grain.","promptSha256":"f6542bbed09eb34e7e113790973b453e5134c9b9a8e7f7d5d4573836857e16b6","sourcePromptAvailable":true,"sourceAuditStatus":"verified-2026-11-15","sourceRecordId":"01a0145e-aa37-72da-808b-2a53e00d8641","sourceMediaId":"WAiLOWcxp9CP4nMIIKGHu4wqNpH2TmwUilKebkYq","sourceTitle":"Underwater Huggs","sourceSlug":"underwater-huggs","sourceModel":"banana3","sourceModelFamily":"banana","sourceAspect":"3:4","sourceMinFiles":1,"sourceGenerationSettings":{"image_size":"2K","model_type":"banana3","aspect_ratio":"3:4"}},
